 86	    private Node insert(Node current, int data, InsertionState state) {
 87	        boolean redRedConflict = false;
 88	
 89	        if (current == null) {
 90	            return new Node(data, Color.RED);
 91	        }
 92	
 93	        if (data < current.data) {
 94	            current.left = insert(current.left, data, state);
 95	            current.left.parent = current;
 96	            redRedConflict = current != root && isRed(current) && isRed(current.left);
 97	        } else {
 98	            current.right = insert(current.right, data, state);
 99	            current.right.parent = current;
100	            redRedConflict = current != root && isRed(current) && isRed(current.right);
101	        }
102	
103	        current = applyPendingRotation(current, state);
104	
105	        if (redRedConflict) {
106	            resolveRedRedConflict(current, state);
107	        }
