112	    private Node applyPendingRotation(Node current, InsertionState state) {
113	        switch (state.pendingRotation) {
114	            case LEFT_LEFT:
115	                current = rotateLeft(current);
116	                recolorAfterSingleRotation(current, current.left);
117	                break;
118	            case RIGHT_RIGHT:
119	                current = rotateRight(current);
120	                recolorAfterSingleRotation(current, current.right);
121	                break;
122	            case RIGHT_LEFT:
123	                current.right = rotateRight(current.right);
124	                current.right.parent = current;
125	                current = rotateLeft(current);
126	                recolorAfterSingleRotation(current, current.left);
127	                break;
128	            case LEFT_RIGHT:
129	                current.left = rotateLeft(current.left);
130	                current.left.parent = current;
131	                current = rotateRight(current);
132	                recolorAfterSingleRotation(current, current.right);
133	                break;
134	            case NONE:
135	                break;
136	        }
137	
138	        state.pendingRotation = Rotation.NONE;
139	        return current;
140	    }
