142	    private void resolveRedRedConflict(Node current, InsertionState state) {
143	        Node parent = current.parent;
144	        Side side = sideOf(parent, current);
145	        Node uncle = siblingChild(parent, side);
146	
147	        if (isBlack(uncle)) {
148	            state.pendingRotation = chooseRotation(current, side);
149	        } else {
150	            recolorForRedUncle(current, uncle);
151	        }
152	    }
