167	    private Rotation chooseRotation(Node current, Side side) {
168	        if (side == Side.RIGHT) {
169	            if (isRed(current.left)) {
170	                return Rotation.RIGHT_LEFT;
171	            }
172	            if (isRed(current.right)) {
173	                return Rotation.LEFT_LEFT;
174	            }
175	        } else {
176	            if (isRed(current.left)) {
177	                return Rotation.RIGHT_RIGHT;
178	            }
179	            if (isRed(current.right)) {
180	                return Rotation.LEFT_RIGHT;
181	            }
182	        }
183	
184	        return Rotation.NONE;
185	    }
