188	        Node pivot = node.right;
189	        Node transferredSubtree = pivot.left;
190	
191	        pivot.left = node;
192	        pivot.parent = node.parent;
193	        node.parent = pivot;
194	        node.right = transferredSubtree;
195	
196	        if (transferredSubtree != null) {
197	            transferredSubtree.parent = node;
198	        }
199	
200	        return pivot;
201	    }
