203	    private Node rotateRight(Node node) {
204	        Node pivot = node.left;
205	        Node transferredSubtree = pivot.right;
206	
207	        pivot.right = node;
208	        pivot.parent = node.parent;
209	        node.parent = pivot;
210	        node.left = transferredSubtree;
211	
212	        if (transferredSubtree != null) {
213	            transferredSubtree.parent = node;
214	        }
215	
216	        return pivot;
