13	    static String formatTree(RedBlackTreeSnapshot snapshot) {
14	        StringBuilder builder = new StringBuilder();
15	        appendTree(snapshot.root(), 0, builder);
16	        return builder.toString();
17	    }
18	
19	    private static void appendInorder(RedBlackTreeSnapshot.NodeSnapshot node, StringBuilder builder) {
20	        if (node == null) {
21	            return;
22	        }
23	
24	        appendInorder(node.left(), builder);
25	        if (builder.length() > 0) {
26	            builder.append(' ');
27	        }
28	        builder.append(node.data());
29	        appendInorder(node.right(), builder);
30	    }
31	
32	    private static void appendTree(RedBlackTreeSnapshot.NodeSnapshot node, int space, StringBuilder builder) {
33	        if (node == null) {
34	            return;
35	        }
36	
37	        int nextSpace = space + PRINT_INDENT;
38	        appendTree(node.right(), nextSpace, builder);
39	        builder.append('\n');
40	        for (int i = PRINT_INDENT; i < nextSpace; i++) {
41	            builder.append(' ');
42	        }
43	        builder.append(node.data()).append('\n');
44	        appendTree(node.left(), nextSpace, builder);
45	    }
46	}

